import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); String line = br.readLine(); if (line != null) { int t = Integer.parseInt(line.trim()); while (t-- > 0) { String nStr = br.readLine(); if (nStr == null) break; int sum = 0; for (int i = 0; i < nStr.length(); i++) { sum += (nStr.charAt(i) - '0'); } out.println(sum); } } out.flush(); out.close(); } }